import pandas as pd
from datetime import timedelta

def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"].copy()
    cdc = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Determine high watermark timestamp
    if len(watermark) > 0:
        high_ts = watermark["high_ts"].iloc[0]
    else:
        high_ts = pd.Timestamp.min

    # Build state dict from target_snapshot
    state = {}
    for _, row in target.iterrows():
        state[row["user_id"]] = {
            "email": row["email"],
            "status": row["status"],
            "status_ts": row["status_ts"],
        }

    # Filter cdc events strictly after high watermark
    events = cdc[cdc["event_ts"] > high_ts].copy()

    # Sort sequentially per user by (event_ts, event_seq)
    events = events.sort_values(by=["user_id", "event_ts", "event_seq"], kind="mergesort")

    for _, ev in events.iterrows():
        uid = ev["user_id"]
        op = ev["op"]
        ts = ev["event_ts"]
        email = ev["email"]

        current = state.get(uid)

        if op == "D":
            # Soft delete: status -> DELETED, status_ts = ts, email preserved
            preserved_email = current["email"] if current is not None else email
            state[uid] = {
                "email": preserved_email,
                "status": "DELETED",
                "status_ts": ts,
            }
        elif op == "U":
            if current is None:
                # New user: upsert
                state[uid] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": ts,
                }
            elif current["status"] == "ACTIVE":
                state[uid] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": ts,
                }
            elif current["status"] == "DELETED":
                threshold = current["status_ts"] + timedelta(days=7)
                if ts > threshold:
                    # Resurrection
                    state[uid] = {
                        "email": email,
                        "status": "ACTIVE",
                        "status_ts": ts,
                    }
                # else: discard, no change
        # unknown op types ignored (not specified)

    # Build output DataFrame
    rows = []
    for uid, s in state.items():
        rows.append({
            "user_id": uid,
            "email": s["email"],
            "status": s["status"],
            "status_ts": s["status_ts"],
        })

    new_snapshot = pd.DataFrame(rows, columns=["user_id", "email", "status", "status_ts"])

    # Ensure dtypes align with expected output
    if len(new_snapshot) > 0:
        new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
        new_snapshot["status_ts"] = pd.to_datetime(new_snapshot["status_ts"])
    else:
        new_snapshot = pd.DataFrame({
            "user_id": pd.Series(dtype="int64"),
            "email": pd.Series(dtype="object"),
            "status": pd.Series(dtype="object"),
            "status_ts": pd.Series(dtype="datetime64[us]"),
        })

    return {"new_snapshot": new_snapshot}
